use super::*;

/// A leaf's SIGNATURE text (parameters + return type) — where type-coupling shows, without the body's
/// incidental mentions.
///
/// `node` is the FUNCTION node, not the statement that binds it: Rust's `function_item`, TypeScript's
/// `function_declaration`, or the `arrow_function` an arrow const is bound to. All three carry the same
/// two fields, which is why one implementation serves both grammars.
///
/// The `parameter` fallback is TypeScript's single-argument arrow. `x => x.trim()` has no parenthesized
/// list at all, so tree-sitter gives it a `parameter` field rather than a `parameters` one; without the
/// fallback every such leaf reads as having an EMPTY signature and can never be type-coupled. Rust has
/// no such field, so the Rust path is unchanged.
pub(crate) fn leaf_signature(node: Node, src: &[u8]) -> String {
    let mut s = String::new();
    if let Some(p) = node.child_by_field_name("parameters").or_else(|| node.child_by_field_name("parameter")) {
        s.push_str(p.utf8_text(src).unwrap_or(""));
    }
    if let Some(r) = node.child_by_field_name("return_type") {
        s.push(' ');
        s.push_str(r.utf8_text(src).unwrap_or(""));
    }
    s
}
